使用::property.isInitialized检查或使用可空类型：
```kotlin
// 危险
class MyActivity : AppCompatActivity() {
    lateinit var viewModel: MainViewModel

    fun someMethod() {
        viewModel.doSomething() // 如果onCreate前调用则崩溃
    }
}

// 安全 - 检查初始化状态
class MyActivity : AppCompatActivity() {
    lateinit var viewModel: MainViewModel

    fun someMethod() {
        if (::viewModel.isInitialized) {
            viewModel.doSomething()
        }
    }
}

// 更推荐 - 使用委托或可空类型
class MyActivity : AppCompatActivity() {
    private val viewModel: MainViewModel by viewModels()
    // viewModels委托自动在需要时初始化
}
```

使用CoroutineExceptionHandler或在launch中使用try-catch：
```kotlin
// 危险 - 未处理异常
viewModelScope.launch {
    val data = api.fetchData() // 网络异常未处理 -> 崩溃
    updateUI(data)
}

// 安全 - try-catch
viewModelScope.launch {
    try {
        val data = api.fetchData()
        updateUI(data)
    } catch (e: IOException) {
        showError("网络错误")
    }
}

// 安全 - CoroutineExceptionHandler
val handler = CoroutineExceptionHandler { _, exception ->
    Log.e("Coroutine", "异常: ${exception.message}")
}
viewModelScope.launch(handler) {
    val data = api.fetchData()
    updateUI(data)
}
```

对嵌套引用类型进行深拷贝：
```kotlin
// 问题
data class Order(val items: List<Item>, val total: Double)
data class Item(val name: String, var price: Double)

val order1 = Order(listOf(Item("A", 10.0)), 10.0)
val order2 = order1.copy() // items是同一List引用！

// order1和order2的items列表是同一对象
// 注意：如果List内元素可变，修改会影响两者

// 安全 - 深拷贝嵌套结构
data class Order(val items: List<Item>, val total: Double) {
    fun deepCopy() = copy(
        items = items.map { it.copy() } // 深拷贝列表
    )
}
val order2 = order1.deepCopy()
```

合理使用不同Dispatcher：
```kotlin
// 危险 - 主线程执行IO
viewModelScope.launch {
    withContext(Dispatchers.Main) {
        val data = database.query() // 主线程执行数据库！
        textView.text = data.toString()
    }
}

// 正确 - IO切换到Main更新UI
viewModelScope.launch {
    val data = withContext(Dispatchers.IO) {
        database.query() // IO线程执行
    }
    textView.text = data.toString() // 自动在Main（viewModelScope默认）
}

// 注意：viewModelScope.launch默认在Dispatchers.Main
// 只有耗时操作才需要withContext(Dispatchers.IO)
viewModelScope.launch {
    // 这里已经是主线程
    val result = withContext(Dispatchers.IO) {
        heavyComputation() // 耗时操作切IO
    }
    // 回到主线程更新UI
    textView.text = result.toString()
}
```

使用repeatOnLifecycle管理Flow收集：
```kotlin
// 危险 - 未管理生命周期
class MyFragment : Fragment() {
    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        viewLifecycleOwner.lifecycleScope.launch {
            viewModel.dataFlow.collect { data -> // 即使View销毁仍在收集
                updateUI(data)
            }
        }
    }
}

// 安全 - 使用repeatOnLifecycle
class MyFragment : Fragment() {
    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.dataFlow.collect { data ->
                    // 仅在STARTED~STOPPED之间收集
                    updateUI(data)
                }
            }
        }
    }
}

// 或使用flowWithLifecycle
viewLifecycleOwner.lifecycleScope.launch {
    viewModel.dataFlow
        .flowWithLifecycle(viewLifecycleOwner.lifecycle, Lifecycle.State.STARTED)
        .collect { data -> updateUI(data) }
}
```

确保when穷尽所有分支或添加else：
```kotlin
// 危险 - enum新增值时可能遗漏
when (status) {
    Status.LOADING -> showLoading()
    Status.SUCCESS -> showContent()
    // Status.ERROR 遗漏！
}

// 安全 - 穷尽或else
when (status) {
    Status.LOADING -> showLoading()
    Status.SUCCESS -> showContent()
    Status.ERROR -> showError()
}

// 安全 - else兜底
when (status) {
    Status.LOADING -> showLoading()
    Status.SUCCESS -> showContent()
    else -> showError("未知状态")
}

// 作为表达式必须穷尽
val message = when (status) {
    Status.LOADING -> "加载中"
    Status.SUCCESS -> "完成"
    Status.ERROR -> "失败"
    // 如果是sealed class/enum，编译器会检查穷尽
}
```

对Java返回值显式声明可空性并做检查：
```kotlin
// Java方法
public String getName() { return null; } // 可能返回null

// 危险 - 平台类型隐式假设非空
val name: String = javaObj.getName() // 如果返回null则NPE
val length = javaObj.getName().length // NPE!

// 安全 - 显式声明可空
val name: String? = javaObj.getName()
val length = name?.length ?: 0

// 安全 - 使用let处理
javaObj.getName()?.let { name ->
    println(name.length)
}

// 使用@Nullable/@NotNull注解帮助编译器
// 或在Java侧添加注解
```
